starter.javascript:
function unique(nums) {
  const sorted = [...nums].sort()
  return sorted.filter((n, i) => i === 0 || n !== sorted[i - 1])
}

starter.typescript:
function unique(nums: number[]): number[] {
  const sorted = [...nums].sort()
  return sorted.filter((n, i) => i === 0 || n !== sorted[i - 1])
}

solution.javascript:
function unique(nums) {
  const seen = new Set()
  return nums.filter((n) => {
    if (seen.has(n)) return false
    seen.add(n)
    return true
  })
}

solution.typescript:
function unique(nums: number[]): number[] {
  return [...new Set(nums)]
}
